
import { readdir, readFile, writeFile } from "node:fs/promises";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const typesDirectory = resolve(
  dirname(fileURLToPath(import.meta.url)),
  "../src/types",
);

const generatedHeader = `/**
 * @file Generated OpenAPI TypeScript artifact.
 * Owner: Rutva - Task: S2-RUT-1 - Issue: #180
 * Generated by @hey-api/openapi-ts. Do not edit by hand.
 */

`;

/**
 * Adds required file headers to generated TypeScript files.
 * @param {string} directory - Directory to scan recursively.
 * @returns {Promise<void>}
 */
async function addHeaders(directory) {
  const entries = await readdir(directory, { withFileTypes: true });

  for (const entry of entries) {
    const path = join(directory, entry.name);

    if (entry.isDirectory()) {
      await addHeaders(path);
      continue;
    }

    if (!entry.isFile() || !entry.name.endsWith(".ts")) {
      continue;
    }

    const content = await readFile(path, "utf8");

    if (/@file\b/.test(content.slice(0, 1000))) {
      continue;
    }

    await writeFile(path, generatedHeader + content, "utf8");
    
  }
}

await addHeaders(typesDirectory);
